import fs from 'node:fs';import {createHash} from 'node:crypto';import path from 'node:path';
const file='data/recipes/arabic-youtube/manal-scale-20261021b/finalpackrecipes.json',bytes=fs.readFileSync(file),batch=JSON.parse(bytes);const sha=s=>createHash('sha256').update(s,'utf8').digest('hex');const sort=v=>Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v;let e=[];for(const [i,r] of batch.recipes.entries()){const n=fs.readFileSync(r.sourceEvidence.sourceExtractFile,'utf8');if(sha(n)!==r.sourceEvidence.sourceExtractSha256)e.push(`extract ${i}`);const c={...r};delete c.contentSha256;if(sha(JSON.stringify(sort(c)))!==r.contentSha256)e.push(`recipe ${i}`);if(!fs.existsSync(r.sourceEvidence.sourceExtractFile))e.push(`missing ${i}`);}if(batch.requestLog.length!==batch.underlyingHttpRequestCount)e.push('request log');console.log(JSON.stringify({sha256:sha(bytes.toString('utf8')),records:batch.recipes.length,complete:batch.counts.completeIngredientsAndMethods,extracts:batch.sourceIndex.length,requestLog:batch.requestLog.length,requests:batch.underlyingHttpRequestCount,errors:e.slice(0,10),errorCount:e.length}));
